import { useClaims } from '../claims/claims';
import { periodOf, usePeriods } from '../periods/periods';
import { usePeople } from '../people/people';
import { claimDue, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { csvField } from './ExportPeople';

// The button that downloads the claims as a CSV file: people in list order (retired people included)
// and each person's claims oldest first, with the number, due and period as the claim's row shows
// them (an empty number or period, or n/a, as it is). Quoted and ended as the people export.
export function ExportClaims() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const periods = usePeriods().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const download = () => {
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
    for (const p of people) {
      const own = claims.filter((c) => c.personId === p.id).reverse();
      for (const c of own) {
        lines.push([
          p.name,
          c.number ?? '',
          c.date,
          c.amount,
          claimDue(c, rates, p.grades, rules),
          c.status,
          periodOf(periods, c.dueBy)?.name ?? '',
        ]);
      }
    }
    const csv = lines.map((l) => l.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `claims-${sheet}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <button type="button" data-testid="export-claims" onClick={download}>
      Export claims (CSV)
    </button>
  );
}
import { useClaims } from '../claims/claims';
import { gradeOn, liveHolds, usePeople } from '../people/people';
import { personDue, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useDueRules } from '../settings/settings';

/** A CSV field: wrapped in double quotes, with any quote inside doubled, when it holds a comma, a quote or a line break. */
export function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

// The button that downloads the people as a CSV file: one line per person in list order, retired
// people included, with the grade in force on the sheet's today, the retired-from date (or nothing)
// and the due-total as shown. Lines end with a line feed.
export function ExportPeople() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const download = () => {
    const lines = [['name', 'grade', 'retired-from', 'due-total']];
    for (const p of people) {
      const due = personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules);
      lines.push([p.name, gradeOn(p.grades, today) ?? p.grade, p.retiredFrom ?? '', due]);
    }
    const csv = lines.map((l) => l.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheet}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <button type="button" data-testid="export-people" onClick={download}>
      Export people (CSV)
    </button>
  );
}
import { useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { poolsKey } from '../pools/pools';
import type { Pool } from '../pools/pools';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { csvField } from './ExportPeople';

// The button that downloads the pools as a CSV file: one line per member, pools in the order added and
// members in the order added, a pool member as pool:<name> and the cut as the pool's row shows it (empty
// when none). The pools are re-read from the store first, so the cuts are current. Quoted and ended as
// the people export.
export function ExportPools() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();

  if (!user || !sheet) return null;

  const download = async () => {
    const pools = await queryClient.fetchQuery({
      queryKey: poolsKey(sheet),
      queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheet)}/pools`),
      staleTime: 0,
    });
    const lines = [['pool', 'member', 'share', 'cut']];
    for (const p of pools) {
      for (const m of p.members) {
        lines.push([p.name, m.poolId !== null ? `pool:${m.name}` : m.name, m.share, m.cut]);
      }
    }
    const csv = lines.map((l) => l.map(csvField).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `pools-${sheet}.csv`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  return (
    <button type="button" data-testid="export-pools" onClick={download}>
      Export pools (CSV)
    </button>
  );
}
